    sqlite3 *db;
    int rc = sqlite3_open(":memory:", &db);
    if (rc == SQLITE_OK) {
        printf("Successfully opened in-memory database\n");
        sqlite3_exec(db, "CREATE TABLE test (id INTEGER PRIMARY KEY, name TEXT);", NULL, 0, NULL);
        sqlite3_exec(db, "INSERT INTO test (name) VALUES ('SQLite test');", NULL, 0, NULL);

        char *zErrMsg = 0;
        rc = sqlite3_exec(db, "SELECT name FROM test;", [](void *ctx, int argc, char **argv, char **pzErrMsg) -> int {
            printf("Result: %s\n", argv[0]);
            return SQLITE_OK;
        }, 0, &zErrMsg);

        if (rc != SQLITE_OK) {
            fprintf(stderr, "SQL error: %s\n", zErrMsg);
            sqlite3_free(zErrMsg);
        }

        sqlite3_close(db);
    } else {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(db));
    }
    return ret;
}

